code_example:
std::vector<int> nums = {1, 2, 3, 4, 5};

// Copy (read-only access)
for (int x : nums) {
    // Use x
}

// Reference (modification allowed)
for (int& x : nums) {
    x *= 2;
}

// Const Reference (preferred read-only access)
for (const int& x : nums) {
    // Faster than copy, cannot modify
}

// C-style arrays also work
int arr[] = {10, 20, 30};
for (auto val : arr) {}
